// Parse Tesseract OCR lines into structured receipt items.
// Input: $json.lines (array of strings) from the Tesseract service.
const ocrResult = $input.first().json;
const lines = ocrResult.lines
  || (ocrResult.text ? ocrResult.text.split('\n').map(l => l.trim()).filter(Boolean) : []);

if (!lines.length) {
  throw new Error('OCR returned no text. Check image quality.');
}

// ── Parsing heuristics ───────────────────────────────────────
// Matches receipt lines like:
//   Burger           R45.00
//   Beer x2          R90.00
//   Chips x 3        R75.00
//   Cola             45.00    (no R prefix)
// Skips summary lines (total, vat, service charge, etc.)
const SKIP = ['total', 'subtotal', 'vat', 'tax', 'service', 'gratuity',
              'discount', 'change', 'cash', 'card', 'tip', 'amount due',
              'balance', 'payment'];

// Price at end of line (optional R/r prefix, digits, optional .cents)
const PRICE_RE = /[Rr]?\s*(\d{1,6}(?:[.,]\d{2})?)\s*$/;
// Quantity multiplier embedded in name: x2, x 3, x4
const QTY_RE   = /[xX]\s*(\d+)\s*$/;

const items = [];

for (const line of lines) {
  const lower = line.toLowerCase();
  if (SKIP.some(w => lower.includes(w))) continue;

  // Must end with a price
  const priceMatch = line.match(PRICE_RE);
  if (!priceMatch) continue;

  const priceFloat = parseFloat(priceMatch[1].replace(',', '.'));
  if (isNaN(priceFloat) || priceFloat <= 0) continue;

  // Strip price from name; extract optional quantity
  let name = line.slice(0, line.length - priceMatch[0].length).trim();
  let qty  = 1;
  const qm = name.match(QTY_RE);
  if (qm) {
    qty  = Math.max(1, parseInt(qm[1], 10));
    name = name.slice(0, name.length - qm[0].length).trim();
  }

  // Clean up dots/dashes used as tab-stops on receipts
  name = name.replace(/[.\-]{2,}/g, '').trim();
  if (!name || name.length < 2) continue;

  // Capitalise first letter
  name = name.charAt(0).toUpperCase() + name.slice(1).toLowerCase();

  // Price on receipt is the total for qty; derive unit price
  const unitPriceCents = Math.round((priceFloat / qty) * 100);
  if (unitPriceCents <= 0) continue;

  items.push({ name, unit_price_cents: unitPriceCents, total_quantity: qty });
}

if (!items.length) {
  throw new Error('No receipt items could be parsed. Check image quality or receipt format.');
}

const guest = $('Validate Host Token').first().json;

return [{ json: { party_id: guest.party_id, items } }];

// Build a bulk INSERT SQL for all parsed items.
const { party_id, items } = $('Parse OCR Items').first().json;

if (!items || !items.length) throw new Error('No items to insert');

const params = [];
const valueParts = items.map((item, i) => {
  const base = i * 3;
  params.push(party_id, item.name, item.unit_price_cents);
  return `(uuid_generate_v4(), $${base+1}::uuid, $${base+2}, $${base+3}, ${item.total_quantity})`;
});

const sql = `INSERT INTO items (id, party_id, name, unit_price_cents, total_quantity)
             VALUES ${valueParts.join(', ')}
             RETURNING id, name, unit_price_cents, total_quantity`;

return [{ json: { sql, params, party_id, items } }];
